import sys

def solve():
    t = int(input().split()[0])
    for _ in range(t):
        n, x = list(map(int, input().split()[_+1].split())
        a = list(map(int, x[_].split()))
        min_volume = sys.maxsize
        for i in range(len(a)):
            volume = 0
            for j in range(i+1, len(a)):
                if a[i] <= a[j]:
                    volume += a[j] - a[i]
            if volume > min_volume:
                min_volume = volume
        print(min_volume)

