def solve():
    for _ in range(int(input())):
        s = input()[_]
        n = len(s)
        primes = [2, 3, 5, 7]
        def is_prime(num):
            if num < 2:
                return False
            for i in range(2, int(num ** 0.5) + 1):
                if num % i == 0:
                    return False
            return True

        def delete_digit(s, i):
            return s[:i] + s[i + 1:]

        def check_prime(s):
            for p in primes:
                if is_prime(int(s)):
                    yield s

        def check(s):
            for p in itertools.permutations(s):
                if len(p) > 1:
                    for q in check_prime(p):
                        yield q
                else:
                    yield p

        for p in check(s):
            if len(p) == n - 1:
                yield ''.join(p)
            elif len(p) == 1:
                if is_prime(int(p)):
                    yield p
                else:
                    yield -1

