def solve():
    t = int(input().splitlines[0])
    for _ in range(t):
        n, k = list(map(int, input().splitlines[_].split())
        a = list(map(int, n))
        r1 = 0
        r2 = 0
        for i in range(1, k):
            r1 += abs(a[i] - a[(i + 1) % n])
            r2 += abs(a[(i + 1) % n] - a[i])
        if r1 + r2 < n:
            r1 = 0
            r2 = 0
            for i in range(1, k):
                if a[i] - a[(i + 1) % n] < a[(i + 2) % n]:
                    r1 += 1
                else:
                    r2 += 1
        if r1 < r2:
            r1 = 0
            r2 = 0
            for i in range(1, k):
                if a[(i + 1) % n] - a[i] < a[(i + 2) % n] - a[(i + 1) % n]:
                    r1 += 1
                else:
                    r2 += 1
        print(min(r1, r2))

