def solve():
    t = int(input().split('\n')[0]
    for _ in range(t):
        game = input().split('\n')[_].split()
        x_wins = 0
        o_wins = 0
        p_wins = 0
        for row in game:
            if row.count('X') == 3:
                x_wins += 1
            elif row.count('O') == 3:
                o_wins += 1
            elif row.count('+') == 3:
                p_wins += 1
        for col in zip(*game):
            if col.count('X') == 3:
                x_wins += 1
            elif col.count('O') == 3:
                o_wins += 1
            elif col.count('+') == 3:
                p_wins += 1
        if x_wins > 0:
            print('X')
        elif o_wins > 0:
            print('O')
        elif p_wins > 0:
            print('+')
        else:
            print('DRAW')

