        crosses_won = False
        naughts_won = False
        pluses_won = False
        for i in range(3):
            if board[i][0] == 'X':
                crosses_won = True
                break
            elif board[i][0] == 'O':
                naughts_won = True
                break
            elif board[i][0] == '+':
                pluses_won = True
                break
        if crosses_won:
            print('X')
            sys.exit()
        elif naughts_won:
            print('O')
            sys.exit()
        elif pluses_won:
            print('+')
            sys.exit()
