def solve():
    test_cases = int(input().splitlines[0])
    for test_case in range(test_cases):
        game = input().splitlines[test_case+1:test_case+4]
        result = np.array(game)
        x_wins = np.sum(result == 'X')
        o_wins = np.sum(result == 'O')
        p_wins = np.sum(result == '+')
        if x_wins == 3 or o_wins == 3 or p_wins == 3:
            print('X')
        elif x_wins > o_wins and x_wins > p_wins:
            print('O')
        elif o_wins > x_wins and o_wins > p_wins:
            print('+')
        else:
            print('DRAW')

