def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        max_sum = -sys.maxsize
        min_op = sys.maxsize
        for l in range(n):
            r = n - l
            for i in range(l, r + 1):
                if a[i] < 0:
                    a[i] = -a[i]
