def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        max_sum = -sys.maxsize
        min_op = n
        for l in range(n):
            for r in range(l, n):
                if l < r:
                    subarray = a[l:r]
                    subarray_sum = sum(subarray)
                    if subarray_sum > max_sum:
                        max_sum = subarray_sum
                        min_op = max(min_op, l-r)
        else:
            subarray = a[l:r]
            subarray = [-x for x in subarray]
            subarray_sum = sum(subarray)
            if subarray_sum > max_sum:
                max_sum = subarray_sum
                min_op = max(min_op, l-r)
        print(max_sum, min_op)

