def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        board = list(map(int, input().split()))
        if n == 1:
            print("Bob")
        else:
            alice_wins = False
            for i in range(n):
                for j in range(i, n):
                    if board[i] == board[j]:
                        new_board = board[:]
                        new_board[i] = j
                        new_board[j] = i
                        if not alice_wins:
                            alice_wins = True
                            for k in range(i+1, n):
                                if new_board[k] == new_board[i] == new_board[j]:
                                    new_board[k] = new_board[i] + new_board[j]
                                    if not alice_wins:
                                        alice_wins = True
            if alice_wins:
                print("Alice")
            else:
                print("Bob")

