from functools import reduce
from itertools import chain, accumulate

def solve():
    def divisibility(n, arr):
        return all(i % a == 0 for i, a in enumerate(arr, 1))

    def sum_divisibility(n, arr):
        return all(n % a == 0 for a in arr)

    def generate_perfect_array(n):
        if n == 1:
            return [1]
        else:
            candidates = list(chain.from_iterable(accumulate(range(1, 1001), lambda a, b: [a, a + b])))
            filtered_candidates = [candidate for candidate in candidates if divisibility(n, [candidate])]
            sum_of_filtered_candidates = sum(filtered_candidates)
            if sum_divisibility(n, [sum_of_filtered_candidates]):
                return filtered_candidates
            else:
                return generate_perfect_array(n - 1) + [sum_of_filtered_candidates]

    t = int(input())
    for _ in range(t):
        n = int(input())
        print(list(generate_perfect_array(n)))

