def solve():
    def divisors(n):
        divisors = []
        for i in range(1, int(math.sqrt(n)) + 1):
            if n % i == 0:
                divisors.append(i)
                divisors.append(n // i)
        divisors.sort()
        return divisors

    def perfect_array(n):
        divisors = divisors(n)
        result = [0] * n
        for i in range(1, n + 1):
            result[i - 1] = divisors[i - 1]
        for i in range(2, n):
            result[i - 1] += result[i - 1] // divisors[i] * divisors[i]
        return result

    t = int(input())
    for _ in range(t):
        n = int(input())
        print(perfect_array(n))

