def solve():
    def divisors(n):
        divisors = []
        for i in range(1, int(math.sqrt(n)) + 1):
            if n % i == 0:
                divisors.append(i)
                divisors.append(n // i)
        divisors.sort()
        return divisors

    def perfect_array(n):
        divisors = divisors(n)
        result = [0] * n
        for i in range(n):
            result[i] = divisors[i]
        for i in range(1, n):
            for j in range(i + 1, n):
                if result[i] + result[j] <= n:
                    result[i] += result[j]
                    result[j] = 0
        return result

    t = int(input())
    for _ in range(t):
        n = int(input())
        print(perfect_array(n))

