def is_palindrome(s):
    n = len(s)
    for i in range(n // 2):
        if s[i] != s[n - i - 1]:
            return False
    return True

def solve():
    t = int(input().strip())
    for _ in range(t):
        s = input().strip()
        if is_palindrome(s):
            print(-1)
        else:
            dp = [0] * (len(s) + 1)
            for i in range(1, len(s) + 1):
                for j in range(i, len(s) + 1):
                    if s[i - 1] != s[j - 1]:
                        dp[j] = max(dp[j], dp[i - 1] + 1)
            print(len(s) - dp[-1])

import sys

def solve():
    def is_palindrome(s):
        return s == s[::-1]

    def find_longest_non_palindrome(s):
        n = len(s)
        dp = [[0] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = 1
            for j in range(i - 1, -1, -1):
                if s[i] == s[j] and dp[j + 1][i - 1] == 1:
                    dp[j][i] = dp[i][i]
                else:
                    dp[j][i] = max(dp[j + 1][i], dp[j][i - 1]) + 1
        return n - max(dp[0], dp[-1])

    t = int(input())
    for _ in range(t):
        s = input().strip()
        if all(c == c[::-1] for c in [list(s)]):
            print(-1)
        else:
            print(find_longest_non_palindrome(s))

