def solve():
    def is_palindrome(s):
        return s == s[::-1]

    def longest_non_palindrome(s):
        n = len(s)
        dp = [[0] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = 1
        max_len = 0
        for k in range(2, n + 1):
            for i in range(n - k + 1):
                j = i + k - 1
                if is_palindrome(s[i:j]):
                    dp[i][j] = dp[i + 1][j - 1]
                else:
                    dp[i][j] = dp[i + 1][j] + 1
                    max_len = max(max_len, dp[i][j])
        return n - max_len

    t = int(input())
    for _ in range(t):
        s = input()
        if not is_palindrome(s):
            print(len(s))
        else:
            print(longest_non_palindrome(s))

