def solve():
    def dfs(index, count, cur_sum, cur_product, memo):
        if index == n:
            if count == k:
                result.append(cur_product)
                return
            return

        if (index, count, cur_sum, cur_product) in memo:
            return
        memo[(index, count, cur_sum, cur_product)] = True

        dfs(index + 1, count, cur_sum, cur_product, memo)
        if cur_sum > 0:
            dfs(index + 1, count + 1, cur_sum - 1, cur_product * -1, memo)
        else:
            dfs(index + 1, count, cur_sum + 1, cur_product * 1, memo)

    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        result = []
        memo = set()
        dfs(1, 0, 0, 1, memo)
        if len(result) == 0:
            print("NO")
        else:
            print("YES")
            print(*result)

import math

def solve():
    def is_valid(a, k):
        count = 0
        for i in range(len(a)):
            for j in range(i+1, len(a)):
                if a[i] * a[j] == 1:
                    count += 1
        return count == k

    def generate_array(n, k):
        if k > math.comb(n-1, 2) // 2:
            return None

        a = [1]
        for i in range(1, n):
            if len(a) <= k:
                a.append(-1)
            else:
                a[-1] *= -1
                if is_valid(a, k):
                    return a

        return None

    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        result = generate_array(n, k)
        if result is None:
            print("NO")
        else:
            print("YES")
            print(*result)

import itertools

def solve():
    def a_characteristic(a):
        return len(list(itertools.combinations(a, 2) if all(x == 1 or x == -1 for x in a) else []))

    def find_array(n, k):
        if k > (n - 1) * n // 2:
            return "NO"
        if k == 0:
            return "YES\n1 -1"
        for i in range(1, n):
            if a_characteristic(list(range(1, i)) + [-1] + list(range(i, n)) + [-1]) == k:
                return "YES\n" + "\n".join(map(str, (1, -1) + list(range(1, i)) + list(range(i, n))) + [-1])
        return "NO"

    t = int(input())
    for _ in range(t):
        n, k = map(int, input().split())
        print(find_array(n, k))

