def solve():
    def count_pairs(a, n, k):
        count = 0
        for i in range(n - 1):
            for j in range(i + 1, n):
                if a[i] * a[j] == 1:
                    count += 1
        return count

    def generate_array(n, k):
        a = [1]
        while len(a) < n:
            if count_pairs(a, len(a), k) == k:
                return a
            a.append(-1)
            for i in range(len(a) - 1, -1, -1):
                if count_pairs(a, i, k - count_pairs(a[:i], i, k)) == k - count_pairs(a[:i], i, k):
                    a[i] = -a[i]
                    break
        return a

    t = int(input().strip())
    for _ in range(t):
        n, k = map(int, input().strip().split())
        if k > math.comb(n - 1, 2):
            print("NO")
        else:
            print("YES")
            print(*generate_array(n, k))

