from typing import List

def solve():
    def beauty(arr: List[int]):
        n = len(arr)
        if n <= 1:
            return 0
        return max(a * b for a, b in zip(arr, arr[1:]))

    @functools.lru_cache(maxsize=None)
    def remove_elements(arr: List[int], k: int) -> List[int]:
        if k == 0:
            return arr
        return remove_elements(arr[1:], k - 1) if arr[0] > arr[1] else remove_elements(arr[1:], k)

    def max_beauty(arr: List[int]):
        n = len(arr)
        if n == 1:
            return 0
        max_beauty = 0
        for i in range(1, n):
            max_beauty = max(max_beauty, arr[i - 1] * arr[i] + max_beauty)
            arr = remove_elements(arr, i)
        return max(max_beauty, arr[0] * arr[1])

