        return sum(1 for member in members if member[opinion] == '+')

    def count_disagree(members, opinion):
        return sum(1 for member in members if member[opinion] == '-')

    max_members = 1
    for i in range(1, n):
        for expulsions in itertools.combinations(range(1, n), i):
            remaining_members = [members[j] for j in range(1, n) if j not in expulsions]
            for opinion in range(k):
                if count_agree(remaining_members, opinion) > count_disagree(remaining_members, opinion):
                    break
            else:
                max_members = max(max_members, len(remaining_members))

    print(max_members + 1)

