def solve():
    def count_agree(members, opinions):
        return sum(1 for member, opinion in zip(members, opinions) if member == opinion)

    def max_members(n, k, members, opinions):
        max_members = 1
        for i in range(1, n):
            for expel in range(i):
                for subset in itertools.combinations(range(1, n), expel):
                    new_members = list(set(members) - set(subset))
                    new_opinions = [opinions[i] for i in new_members]
                    if count_agree(new_members, new_opinions) > count_agree(new_members, [opinions[i] for i in subset]):
                        new_members.append(subset[0])
                    else:
                        new_members += subset
                    if len(new_members) > max_members:
                        max_members = len(new_members)
        return max_members + 1

    t = int(input())
