import collections

def solve():
    n, k = map(int, input().split())
    members = [list(input()) for _ in range(n)]
    max_members = n

    # Count agreement and disagreement for each opinion
    counts = collections.defaultdict(lambda: (0, 0))
    for member in members:
        for i in range(k):
            if member[i] == '+':
                counts[i][0] += 1
            else:
                counts[i][1] += 1

    # Find opinions with the minimum agreement and maximum disagreement
    min_agree, max_disagree = float('inf'), -float('inf')
    for count in counts.values():
        agree, disagree = count
        if agree < min_agree:
            min_agree = agree
        if disagree > max_disagree:
            max_disagree = disagree

    # Check if there is a tie
    if min_agree == max_disagree:
        max_members = 0
    else:
        # Calculate the maximum number of members that can stay
        max_members = sum(count[0] > count[1] for count in counts.values())

    print(max_members)

