                continue

            new_distance = current_distance + 1
            if neighbor[1] not in distances or new_distance < distances[neighbor[1]]:
                distances[neighbor[1]] = new_distance
                heapq.heappush(priority_queue, (new_distance, neighbor[1]))

    return -1

