import heapq

def dijkstra(start, end, grid):
    queue = [(0, start)]
    visited = set()
    while queue:
        _, current = heapq.heappop(queue)
        if current == end:
            return current
        visited.add(current)
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            next_point = (current[0] + dx, current[1] + dy)
            if 0 <= next_point[0] < len(grid[0]) and 0 <= next_point[1] < len(grid) and grid[next_point[1]][next_point[0]] and next_point not in visited:
                heapq.heappush(queue, (current[0] + 1, next_point))
                grid[next_point[1]][next_point[0]] = False
    return None

