    for _ in range(t):
        a, b = map(int, input().split())
        print(dijkstra((0, 0), (a, b), {(0, 0): 0}) + 1)
        jumps = dijkstra((0, 0), (a, b), {(0, 0): 0})
        path = []
        current = (0, 0)
        for _ in range(jumps):
            path.append(current)
            neighbors = [(current[0] + 2 * dx, current[1] + 2 * dy) for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]]
            next_node = min(neighbors, key=lambda n: manhattan_distance(n, (a, b)))
            current = next_node
        print(*path, sep='\n')

