def solve():
    def insert_digit(num: str, pos: int, digit: int) -> str:
        return num[:pos] + str(digit) + num[pos:]

    def max_insert_pos(num: str, digit: int) -> int:
        return max(range(len(num) + 1), key=lambda pos: int(insert_digit(num, pos, digit)) if pos > 0 else digit)

    @functools.lru_cache(maxsize=None)
    def max_insert_pos_memo(num: str, digit: int, pos: int = 0) -> int:
        if pos == len(num):
            return digit
        return max(max_insert_pos_memo(num, digit, pos + 1), max_insert_pos(num[pos:], digit))

    def solve_test_case(n: int, d: int, num: str) -> str:
        max_pos = max_insert_pos_memo(num, d)
        return insert_digit(num, max_pos, d)

    t = int(input())
    for _ in range(t):
        n, d = map(int, input().split())
        num = input()
        print(solve_test_case(n, d, num))

