def solve():
    q = collections.deque()
    spells = {1: (2, -1), 2: (2, 1)}
    visited = set()

    def dfs(candies):
        if candies in visited:
            return False
        visited.add(candies)
        if candies == 1:
            q.append((1, []))
            return True
        for spell, change in spells.items():
            if dfs(candies + change):
                q.append((spell, [change] * change))
                return True
        return False

    for n in map(int, input().split()):
        if dfs(1):
            steps, spells_used = q.popleft()
            print(len(spells_used))
            print(*spells_used)
        else:
            print(-1)

