def lex_min_string(s):
    @functools.lru_cache(maxsize=None)
    def dfs(i, prev):
        if i == len(s):
            return s[::-1]
        min_val = float('inf')
        for j in range(i, len(s)):
            if s[j] < prev:
                new_s = s[:j] + s[i] + s[j+1:i] + s[j] + s[i+1:]
                new_val = dfs(i+1, s[j])
                min_val = min(min_val, new_val)
        return min_val

    return dfs(0, None)

