def solve():
    R, C = 201, 201
    board = [[float('inf')] * C for _ in range(R)]
    board[0][0] = 0
    q = [(0, 0, 0)]

    moves = [(0, 0), (0, 1), (0, -1), (1, 0), (-1, 0)]

    while q:
        r, c, steps = heapq.heappop(q)

        for dr, dc in moves:
            new_r, new_c = r + dr, c + dc
            if new_r < 0 or new_r >= R or new_c < 0 or new_c >= C:
                continue
            new_steps = steps + 1
            if new_steps > board[new_r][new_c]:
                board[new_r][new_c] = new_steps
                heapq.heappush(q, (new_r, new_c, new_steps))

    a, b = map(int, input().split())
    return board[a][b]

