    def max_likes(a, i):
        if i == 0:
            return 0 if a[0] < 0 else 1
        return max(max_likes(a, i - 1) + 1 if a[i - 1] > 0 else max_likes(a, i - 1), max_likes(a[i:], i))

    @functools.lru_cache(maxsize=None)
    def min_likes(a, i):
        if i == 0:
            return 0 if a[0] > 0 else -1
        return min(min_likes(a, i - 1) - 1 if a[i - 1] < 0 else min_likes(a, i - 1), min_likes(a[i:], i))

