from collections import deque

def solve(n, actions):
    recent_actions = deque([i for i in range(1, n + 1)])
    actions_queue = deque(actions)
    result = [-1] * n

    while actions_queue:
        time, post = actions_queue.popleft()
        if post <= len(recent_actions):
            recent_actions.rotate(-(post - 1))
        else:
            recent_actions.popleft()
            recent_actions.append(post)

        if recent_actions[0] == result[0]:
            result[0] = -1
        for i in range(1, n):
            if recent_actions[i] != recent_actions[i - 1] and recent_actions[i] != result[i]:
                result[i] = time
                break

    return result

def solve():
    def swap(a, i, j):
        a[i], a[j] = a[j], a[i]
        a_copy = a[:]
        a_copy[j], a_copy[i] = a_copy[i], a_copy[j]
        return a_copy

    def max_index(arr):
        return arr.index(max(arr))

    def can_swap(a, b):
        return max_index(a) == len(a) - 1 and max_index(b) == len(b) - 1

    while True:
        n = int(input())
        a = list(map(int, input().split()))
        b = list(map(int, input().split()))

        if can_swap(a, b):
            print("Yes")
        else:
            print("No")

