def solve():
    n, m = map(int, input().split())
    x1, y1, x2, y2 = map(int, input().split())
    graph = defaultdict(list)
    for i in range(n):
        row = list(input().strip())
        for j in range(m):
            if row[j] == '#':
                graph[(i, j)].append((i, j + 1))
                graph[(i, j)].append((i + 1, j))
                if j > 0:
                    graph[(i, j - 1)].append((i, j))
                if i > 0:
                    graph[(i - 1, j)].append((i, j))
    obstacles = set()
    obstacles_count = 0
    while True:
        new_graph = defaultdict(list)
        for cell in graph:
            if cell != (x1, y1) and cell != (x2, y2):
                if not bfs(graph, cell, (x2, y2)):
                    new_graph[cell] = graph[cell]
                    obstacles_count += 1
                    obstacles.add(cell)
                else:
                    new_graph[cell] = graph[cell]
        if len(new_graph) == len(graph):
            break
        graph = new_graph
        for obstacle in obstacles:
            for neighbor in graph[obstacle]:
                graph[neighbor].remove(obstacle)
    return obstacles_count

