from heapq import heappush, heappop

def solve():
    t = int(input())
    for _ in range(t):
        n, m, x1, y1, x2, y2 = map(int, input().split())
        grid = [[0] * m for _ in range(n)]
        obstacles = []

        def in_bounds(r, c):
            return 0 <= r < n and 0 <= c < m

        def neighbors(r, c):
            result = []
            if in_bounds(r + 1, c):
                result.append((r + 1, c))
            if in_bounds(r - 1, c):
                result.append((r - 1, c))
            if in_bounds(r, c + 1):
                result.append((r, c + 1))
            if in_bounds(r, c - 1):
                result.append((r, c - 1))
            return result

        def dijkstra(start_r, start_c):
            dist = defaultdict(lambda: float('inf'))
            dist[start_r, start_c] = 0
            queue = [(0, start_r, start_c)]

            while queue:
                d, r, c = heappop(queue)

                for neighbor_r, neighbor_c in neighbors(r, c):
                    new_d = d + 1
                    if new_d < dist[(neighbor_r, neighbor_c)]:
                        dist[(neighbor_r, neighbor_c)] = new_d
                        heappush(queue, (new_d, neighbor_r, neighbor_c))

            return dist[(x2, y2)]

        for r in range(n):
            for c in range(m):
                if (r, c) != (x1, y1) and (r, c) != (x2, y2):
                    dist = dijkstra(r, c)
                    if dist == float('inf'):
                        obstacles.append((r, c))
                    else:
                        break

        print(len(obstacles))

