def solve():
    def move(x, y, direction):
        if direction == 'L':
            return x - 1, y
        elif direction == 'R':
            return x + 1, y
        elif direction == 'U':
            return x, y - 1
        elif direction == 'D':
            return x, y + 1
        else:
