    def is_valid_move(x, y, direction):
        if x < 0 or y < 0:
            return False
        return True

    def can_reach_candy(s):
        x, y = 0, 0
        for direction in s:
            x, y = move(x, y, direction)
            if is_on_candy(x, y):
                return True
            if not is_valid_move(x, y, direction):
                return False
        return False

    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input()
        if can_reach_candy(s):
