def solve():
    def is_palindrome(s):
        return s == s[::-1]

    def invert_segment(s, l, r):
        s[l:r+1] = ['1' if c == '0' else '0' for c in s[l:r+1])
        return s

    def can_be_palindrome(s):
        odd_count = collections.Counter(s)['1']
        if odd_count > 1:
            return False
        mid = len(s) // 2
