        if not n:
            break
        s = input()
        if can_be_palindrome(s):
            print("Yes")
        else:
            for i in range(1, len(s)):
                if can_be_palindrome(invert_segment(s, i, i)):
                    print("Yes")
                    break
            else:
                print("No")

import functools

def solve():
    @functools.lru_cache(maxsize=None)
    def is_palindrome(s):
        return s == s[::-1]

    @functools.lru_cache(maxsize=None)
    def invert(s, l, r):
        return ''.join(('1' if c == '0' else '0' if c == '1' else c) for c in s[l-1:r+1])

    def can_be_palindrome(s):
        n = len(s)
        for i in range(1, n):
            if is_palindrome(invert(s, i, i)) and is_palindrome(s[:i] + invert(s, i, n-i)):
                return True
        return False

    while True:
        n = int(input())
        if not n:
            break
        s = input()
        if can_be_palindrome(s):
            print("Yes")
        else:
            print("No")

