import functools
from typing import List

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def is_good(arr):
    return gcd(arr[0], arr[1:]) <= len(arr)

def is_beautiful(arr):
    for i in range(1, len(arr)):
        if not is_good(arr[:i]):
            return False
    return True

def reorder(arr):
    n = len(arr)
    @functools.lru_cache(maxsize=None)
    def gcd_sub(i, j):
        if i == j:
            return arr[i]
        return gcd(arr[i], gcd_sub(i + 1, j))

    def find_min_gcd(i):
        min_gcd = gcd_sub(i, n - 1)
        min_index = i
        for j in range(i + 1, n):
            if gcd_sub(j, n - 1) < min_gcd:
                min_gcd = gcd_sub(j, n - 1)
                min_index = j
        return min_index

    for i in range(1, n):
        j = find_min_gcd(i)
        arr[i], arr[j] = arr[j], arr[i]
        if not is_good(arr[:i + 1]):
            return False
    return True

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        if is_beautiful(arr):
            print("Yes")
        elif reorder(arr):
            print("Yes")
        else:
            print("No")

