def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def is_good(arr):
    return all(gcd(arr[i], arr[j]) <= len(arr) for i in range(len(arr)) for j in range(i, len(arr)))

def is_beautiful(arr):
    for i in range(1, len(arr)):
        if not is_good(arr[:i]):
            return False
    return True

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        arr = list(map(int, input().split()))
        if is_beautiful(arr):
            print("Yes")
        else:
            arr.sort(reverse=True)
            for i in range(1, len(arr)):
                if not is_good(arr[:i]):
                    arr[i], arr[0] = arr[0], arr[i]
                    if is_beautiful(arr):
                        print("Yes")
                        break
            else:
                print("No")

