from typing import List

def solve():
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    def find_k(a: List[int]):
        n = len(a)
        for k in range(1, n - 1):
            if lcm(reduce(lambda x, y: x * y, a[:k], 1) , reduce(lambda x, y: x * y, a[k:], 1)) == a[k]:
                return k
        return -1

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        print(find_k(a))

