from typing import List

def solve():
    def alternating_deck(n: int) -> List[int]:
        alice_white, alice_black, bob_white, bob_black = 1, 0, 0, 0
        for i in range(1, n + 1):
            cards = min(i, n)
            if i % 2 == 1:
                alice_white += cards
                bob_white += cards
            else:
                alice_black += cards
                bob_black += cards * 2
                n -= cards
        return alice_white, alice_black, bob_white, bob_black

    test_cases = int(input())
    for _ in range(test_cases):
        n = int(input())
        result = alternating_deck(n)
        print(*result)

import collections

def solve():
    n = int(input())
    deck = [0] * n
    alice_cards = 0
    bob_cards = 0

    for i in range(1, n + 1):
        cards_to_deal = i
        if i % 2 == 1:
            player = "Alice"
        else:
            player = "Bob"

        while cards_to_deal > 0 and cards_to_deal <= n:
            cards_to_deal -= min(cards_to_deal, n - deck[-1])
            deck[-1] = 0
            if player == "Alice":
                alice_cards += cards_to_deal
            else:
                bob_cards += cards_to_deal
            n -= cards_to_deal

    print(alice_cards, bob_cards)

from collections import defaultdict

def solve():
    def deal_cards(n, player):
        cards = [0] * (n + 1)
        for i in range(1, n + 1):
            cards[i] = cards[i - 1] + (i // 2) * (player == 1)
        return cards[n], cards[n - 1]

    t = int(input())
    for _ in range(t):
        n = int(input())
        alice, bob = deal_cards(n, 1)
        for _ in range(2, n // 2 + 1):
            alice, bob = deal_cards(n, 2)
        print(alice, bob)

from collections import deque

def solve():
    n = int(input())
    deck = deque([0] * n)
    alice, bob = deque([0]), deque([0])

    while deck:
        step = len(deck)
        for _ in range(step):
            if step % 2 == 0:
                alice.append(deck.popleft())
            else:
                bob.append(deck.popleft() * step)

    print(*alice, *bob)

