from math import sqrt, ceil

def solve():
    import sys
    input = sys.stdin.readline

    def manhattan_distance(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def min_cable_length():
        w, d, h = map(int, input().split())
        a, b, f, g = map(int, input().split())

        # Calculate the lengths of the edges of the cuboid
        edge_lengths = [w, d, h, min(w, d), min(w, h), min(d, h)]

        # Calculate the Manhattan distance between the laptop and the projector
        distance = manhattan_distance((a, b), (f, g))

        # Check if the distance is equal to the length of any edge
        for edge in edge_lengths:
            if distance == edge:
                return edge

        # If the distance is not equal to any edge length, calculate the minimum cable length
        # by finding the smallest multiple of the smallest edge length that is greater than or equal to the distance
        smallest_edge = min(edge_lengths)
        return ceil(distance / smallest_edge) * smallest_edge

    for _ in range(int(input())):
        print(min_cable_length())

