def solve():
    t = int(input())
    for _ in range(t):
        w, d, h, a, b, f, g = map(int, input().split())
        x = max(w, d, h)
        y = min(w, d, h)
        if a % x == 0 or b % y == 0 or f % x == 0 or g % y == 0:
            cable_length = manhattan_distance(a, b, f, g)
        elif a % y == 0 or b % x == 0 or f % y == 0 or g % x == 0:
            cable_length = manhattan_distance(a, b, f, g) + (x - a % x) + (y - b % y)
        else:
            cable_length = min(manhattan_distance(a, b, f, g) + (x - a % x) + (y - b % y),
                              manhattan_distance(a, b, f, g) + (x - f % x) + (y - g % y))
        print(cable_length)

