def solve():
    n = int(input())
    times = list(map(int, input().split()))

    walks = []
    for i in range(len(times) - 120):
        if times[i + 120] - times[i] == 120:
            walks.append((times[i], times[i + 120]))

    for i in range(len(times) - 120):
        if times[i] + 120 in times[i + 1:]:
            walks.append((times[i], times[i] + 120))

    for i in range(len(times) - 240):
        if times[i + 120] - times[i] == 120 and times[i + 120 + 120] - times[i + 120] == 120:
            walks.append((times[i], times[i + 120], times[i + 120 + 120]))

    for i in range(len(times) - 120):
        if times[i] + 120 in times[i + 1:] and times[i + 120 + 120] - times[i + 120] == 120:
            walks.append((times[i], times[i] + 120, times[i + 120 + 120]))

    for walk in walks:
        if bisect.bisect_left(times, walk[0]) <= bisect.bisect_right(times, walk[1]) and bisect.bisect_left(times, walk[1] + 120) <= len(times):
            return "YES"

    return "NO"

