@functools.lru_cache(maxsize=None)
def min_abs_value(a):
    n = len(a)
    if n == 1:
        return 0

    dp = [0] * n
    dp[0] = abs(int(a[0]))
    dp[1] = abs(int(a[0]) + int(a[1]))

    for i in range(2, n):
        dp[i] = min(dp[i - 1] + abs(int(a[i]) - int(a[i - 1])), dp[i - 2] + abs(int(a[i - 1]) + int(a[i]) - 2 * int(a[i - 2])))

    return dp[-1]

