def is_degenerate(x1, y1, x2, y2, x3, y3):
    return (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) == 0

def slope(x1, y1, x2, y2):
    return (y2 - y1) / (x2 - x1)

def intercept(x1, y1, slope):
    return y1 - slope * x1

def cut_triangle(x1, y1, x2, y2, x3, y3):
    area = 0.5 * math.fabs((x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)))
    if area == 0:
        return "NO"

    midpoint = ((x1 + x2) / 2, (y1 + y2) / 2)
    if (x1 - x2) == 0:
        if x1 == x3:
            if y1 > max(y2, y3):
                return "YES"
            else:
                return "NO"
        else:
            slope = (y3 - y1) / (x3 - x1)
            intercept_y = intercept(midpoint[0], midpoint[1], slope)
            if y1 <= intercept_y <= y2:
                return "YES"
            else:
                return "NO"
    else:
        slope = (y2 - y1) / (x2 - x1)
        intercept_x = intercept(midpoint[1], midpoint[0], 1 / slope)
        if x1 <= intercept_x <= x2:
            return "YES"
        else:
            return "NO"

