def solve():
    def area(x1, y1, x2, y2, x3, y3):
        return abs(0.5 * math.sqrt((x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) ** 2))

    def cut_triangle(x1, y1, x2, y2, x3, y3):
        x_min, x_max = min(x1, x2, x3), max(x1, x2, x3)
        y_min, y_max = min(y1, y2, y3), max(y1, y2, y3)

        if x_min == x_max:
            return y_min, y_max
        elif y_min == y_max:
            return x_min, x_max
        else:
            m = (y_max - y_min) / (x_max - x_min)
            return x_min + (y_min - m * x_min) / (1 + m), x_max + (y_max - m * x_max) / (1 + m)

    t = int(input().strip())
