from functools import lru_cache

def solve():
    def cost(s):
        a, b = 0, 0
        for c in s:
            if c == '0':
                a += 1
            else:
                b += 1
            yield a * b

    @lru_cache(maxsize=None)
    def max_cost(s, i, j):
        if i > j:
            return 0
        if i == j:
            return cost(s[i:j+1])[-1]
        max_cost_left = max_cost(s, i, j - 1)
        max_cost_right = max_cost(s, i + 1, j)
        return max(max_cost_left, max_cost_right, *cost(s[i:j+1]))

    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input()
        print(max_cost(s, 0, n - 1))

import functools

@functools.lru_cache(maxsize=None)
def cost(s, i, j):
    if i == j:
        return 0
    if i > j:
        return float('inf')
    if s[i] == s[j]:
        return sum(1 for k in range(i+1, j))
    return sum(k**2 for k in range(1, min(j-i+1)))

