                max_cost = max(max_cost, cost_val)
        print(max_cost)

import functools

@functools.lru_cache(maxsize=None)
def max_cost(s, start, end):
    if start == end:
        return 0
    if end - start < 2:
        return float('inf')

    cost = float('inf')
    for i in range(start + 1, end):
        cost = min(cost, max_cost(s, start, i) + max_cost(s, i, end))
    return cost if cost < float('inf') else s[start:end] * s[start:end]

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input()
        print(max_cost(s, 0, n))

