def solve():
    def check_sorted(a):
        for i in range(len(a) - 1):
            if a[i] > a[i + 1]:
                return False
        return True

    def find_swap_or_add(a):
        min_heap = [(i, a[i]) for i in range(len(a))]
        heapq.heapify(min_heap)

        while min_heap:
            i, j = heapq.heappop(min_heap)
            k = min_heap[0][0]
            if j > min_heap[0][1]:
                a[i], a[k] = a[k], a[i]
            else:
                a[i] += j
                if check_sorted(a):
                    return True

        return False

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        if find_swap_or_add(a):
            print("Yes")
        else:
            print("No")

