                rooks[rooks.index(min(rooks, key=lambda x: x[0]))], rooks[move.index(min(move))] = rooks[move.index(min(move))], rooks[rooks.index(min(rooks, key=lambda x: x[0]))]
                # Check if the new positions of the rooks don't attack each other
                if not any(abs(rook[0] - rook2[0]) == abs(rook[1] - rook2[1]) for rook, rook2 in zip(rooks, rooks[1:])):
                    print("YES")
                    break

