        rooks = [(i, j) for i, _ in enumerate(input().split()) for j, _ in enumerate(input().split()) if _ == '1']
        moves = list(itertools.combinations(range(n), 2))
        moves += list(itertools.combinations(range(m), 2))
        moves += list(itertools.product(range(n), repeat=2))
        moves += list(itertools.product(range(m), repeat=2))
        for i in range(m):
            for j in range(i + 1, m):
                if rooks[i] == rooks[j] or (rooks[i][0] == rooks[j][0] and rooks[i][1] == rooks[j][1] + 1) or (rooks[i][0] == rooks[j][0] + 1 and rooks[i][1] == rooks[j][1]):
                    moves.remove((rooks[i], rooks[j]))
                    moves.remove((rooks[j], rooks[i]))
        if dfs([[0]*n + list(range(1, n+1)) for _ in range(n)], rooks, 0, moves):
            print("YES")
        else:
            print("NO")

