import itertools

def solve():
    def dfs(rooks, pos, moves, visited):
        if len(moves) == 0:
            return True

        for next_pos in moves:
            new_rooks = rooks.copy()
            new_rooks.append((next_pos[0], next_pos[1], pos))
            new_visited = visited.copy()
            new_visited[pos] = True
            if not dfs(new_rooks, next_pos, moves[next_pos], new_visited):
                return False

        return True

    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        rooks = []
        moves = {}
        for _ in range(m):
            x, y = map(int, input().split())
            rooks.append((x, y))
            for dx, dy in itertools.product([-1, 0, 1], repeat=2):
                if (dx != 0 and (x + dx < 1 or x + dx > n)) or (dy != 0 and (y + dy < 1 or y + dy > n)):
                    continue
                moves[(x + dx, y + dy)] = moves.get((x + dx, y + dy), []) + [(x, y)]

        visited = [False] * (n * n)
        for pos in rooks:
            visited[pos[0] * n + pos[1]] = True

        if dfs(rooks, None, moves[(n - 1, n - 1)], visited):
            print("YES")
        else:
            print("NO")

