        for i in range(n):
            if i == 0 or i == n - 1:
                continue
            if abs(p[i] - p[(i - 1 if i > 0 else i + 1)]) == 1:
                p.insert(i, p[i])
                break
        else:
            p.insert(i, p[i - 1])
        if len(p) == n:
            print(' '.join(p))
        else:
            print(-1)

