import re

def compare_sizes(a, b):
    a = list(a)
    b = list(b)
    if len(a) == 1 and a[0] == 'M':
        return '<'
    elif len(b) == 1 and b[0] == 'M':
        return '>'
    elif len(a) == 1 and a[0] == 'S':
        return '<' if b[0] == 'M' else: return '>'
    elif len(b) == 1 and b[0] == 'S':
        return '>' if a[0] == 'M' else: return '>'
    elif len(a) == 1 and a[0] == 'L':
        return '<' if b[0] == 'M' else: return '>'
    elif len(b) == 1 and b[0] == 'L':
        return '>' if a[0] == 'M' else: return '>'
    elif a[0] == 'X':
        return '<' if b[0]!= 'X': return '>'
    elif b[0] == 'X':
        return '>' if a[0]!= 'X': return '='
    elif a[0] < b[0]:
        return '<'
    elif a[0] > b[0]:
        return '>'
    else:
        return '='

def solve():
    t = int(input())
    for _ in range(t):
        a, b = input().split()
        print(compare_sizes(a, b))

