def compare_sizes(a, b):
    a = a.replace("M", "1").replace("S", "2").replace("L", "3").replace("X", "4")
    b = b.replace("M", "1").replace("S", "2").replace("L", "3").replace("X", "4")
    a = [int(x) for x in a]
    b = [int(x) for x in b]
    if len(a) < len(b):
        return "<"
    elif len(a) > len(b):
        return ">"
    else:
        if a[0] < b[0]:
            return "<"
        elif a[0] > b[0]:
            return ">"
        else:
            return "="

