import math

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        m = 2
        while True:
            if is_prime(n + m):
                m += 1
            else:
                break
        n += 1
        print(m)

