def solve():
    t = int(input())
    for _ in range(t):
        n, m = input().split()
        n = int(n[0])
        m = int(m[1])

        def is_isolated(x, y):
            return (x + y) % (n + m) == 1

        def find_isolated_cells():
            isolated_cells = []
            for x in range(n):
                for y in range(m):
                    if is_isolated(x, y):
                        isolated_cells.append((x + 1, y + 1))

            if isolated_cells:
                return isolated_cells[0]
            else:
                return (1, 1)

        print(find_isolated_cells())

