    for i in range(1, n):
        for j in range(1, m):
            if dp[i][j] == 1:
                if stanley_path[i - 1] == 0:
                    stanley_path[i] = 1
                    stanley_energy += 1
                elif megan_path[j - 1] == 0:
                    megan_path[j] = 1
                    megan_energy += 1
    if stanley_path[-1] == 1:
        stanley_energy += dp[0][-1]
    if megan_path[-1] == 1:
        megan_energy += dp[0][-1]
    print(stanley_energy + megan_energy)

