def solve():
    t = int(input().split()[0])
    for _ in range(t):
        n, m = map(int, input().split()[_+1].split())
        a = n[0]
        b = n[1]
        if len(a)!= len(b):
            print("NO")
            break
        for op1, op2 in itertools.product(a, b):
            if op1 == op2:
                print("YES")
                break
        else:
            a = [min(a[0] if op1 == 0 else max(a[0] if op1 == 1]
            b = [min(b[0] if op2 == 0 else max(b[0] if op2 == 1]
            a = a[1:] + b[:1]
