def solve():
    t = int(input())
    max_cost = 0
    for p in itertools.permutations(range(1, t + 1)):
        cost = 0
        for i in range(len(p)):
            if i > 0:
                cost += abs(p[i] - p[i - 1])
        if cost > max_cost:
            max_cost = cost
            max_p = p
    print(max_cost)
    print(' '.join(map(str(x) for x in max_p))

