def solve():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        a = [[0 for _ in range(n)]
        for i in range(m):
            a[i] = list(map(int, input().split()))
        for i in range(n):
            for j in range(m):
                if i + 1 < n and j < m:
                    a[i][j] = (i - 1) * m + j
        dp = [[float('inf') for _ in range(n)]
        for i in range(n):
            for j in range(m):
                if i + 1 < n and j < m:
                    dp[i][j] = a[i][j]
        for i in range(n):
            for j in range(m):
                if i + 1 < n and j < m:
                    if dp[i][j] == float('inf'):
                        dp[i][j] = a[i][j]
        pq = []
        for i in range(n):
            for j in range(m):
                if i + 1 < n and j < m:
                    heapq.heappush(pq, (dp[i][j])
        ans = float('inf')
        for i in range(n):
            for j in range(m):
                if i + 1 < n and j < m:
                    if dp[i][j]!= float('inf'):
                        ans = min(ans, dp[i][j])
        print(ans)

